package com.playsphere.review;import com.playsphere.common.Ids;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="reviews") public class Review{@Id @Column(length=36)private String id;@Column(name="author_user_id",nullable=false,length=36)private String authorUserId;@Column(name="target_type",nullable=false,length=24)private String targetType;@Column(name="target_id",nullable=false,length=36)private String targetId;@Column(nullable=false)private int rating;@Column(length=1000)private String comment;@Column(nullable=false,length=24)private String status;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected Review(){}public Review(String u,String type,String target,int rating,String comment){id=Ids.uuid();authorUserId=u;targetType=type;targetId=target;this.rating=rating;this.comment=comment;status="PUBLISHED";createdAt=updatedAt=Instant.now();}public String getId(){return id;}public String getAuthorUserId(){return authorUserId;}public String getTargetType(){return targetType;}public String getTargetId(){return targetId;}public int getRating(){return rating;}public String getComment(){return comment;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void moderate(String s){status=s;updatedAt=Instant.now();}}
